import { API, SignatureKind, SymbolFlags, TypeFlags } from 'typescript-next/unstable/async'
import { SyntaxKind } from 'typescript-next/unstable/ast'
import { discoverFixtures, FIXTURES_ROOT } from './fixtures.ts'
import type { ToolResult, NormalizedProp } from './types.ts'

const tsconfigPath = `${FIXTURES_ROOT}/../tsconfig.json`

// Mirrors RDT 2.4.0's algorithm (lib/parser.js) via tsc --api instead of running RDT itself —
// see docs/type-checker-integration.md ("The algorithm"). Method names are the 7.1 client's.
const api = new API({ cwd: FIXTURES_ROOT })
const parsed = await api.parseConfigFile(tsconfigPath)

const fixtures = discoverFixtures().filter((f) => !f.isDts) // same filter as the RDT baseline
const program = await api.createProgram(
  fixtures.map((f) => f.path),
  parsed.options,
)
const checker = program.project.checker

// A component signature's first parameter is named `props`, or is the only parameter.
async function findComponentSignature(signatures: any[]): Promise<{ param: any } | undefined> {
  for (const sig of signatures) {
    const params = await sig.getParameters()
    if (params.length === 0) continue
    if (params.length === 1 || params[0].name === 'props') return { param: params[0] }
  }
  return undefined
}

// `parent`/`declarations`: the first (resp. every) declaration's parent, when it's an
// interface or type alias (doc step 5). Other parents (e.g. a `cva()` object literal for a
// `VariantProps<...>` prop) are skipped — RDT has no equivalent for those either.
async function declaringTypeNames(prop: any): Promise<string[]> {
  const names: string[] = []
  for (const declHandle of prop.declarations) {
    const node = await declHandle.resolve()
    const p = node?.parent
    if (p && (p.kind === SyntaxKind.InterfaceDeclaration || p.kind === SyntaxKind.TypeAliasDeclaration)) {
      names.push(p.name.getText())
    }
  }
  return names
}

// Props: the type's apparent properties, plus each union member's own apparent properties
// (doc step 3) — the checker's own apparent-properties call already narrows to the
// intersection of a union's members, which drops props that aren't shared across every branch.
async function collectProps(propsType: any): Promise<Map<string, any>> {
  const byName = new Map<string, any>()
  for (const p of await propsType.getApparentProperties()) byName.set(p.name, p)
  if (propsType.flags & TypeFlags.Union) {
    const members = (await propsType.getTypes()) ?? []
    for (const member of members) {
      for (const p of await member.getApparentProperties()) {
        if (!byName.has(p.name)) byName.set(p.name, p)
      }
    }
  }
  return byName
}

async function normalizeProp(prop: any, location: any): Promise<NormalizedProp> {
  const type = await checker.getTypeOfSymbolAtLocation(prop, location)
  const base = await checker.getBaseConstraintOfType(type)
  const typeStr = await checker.typeToString(base ?? type)
  const declarations = await declaringTypeNames(prop)
  return {
    name: prop.name,
    required: !(prop.flags & SymbolFlags.Optional),
    type: typeStr,
    description: await prop.getDocumentationComment(checker),
    parent: declarations[0],
    declarations: declarations.length > 0 ? declarations : undefined,
  }
}

const results: ToolResult[] = []

for (const fixture of fixtures) {
  const start = performance.now()
  try {
    const moduleSymbol = await checker.getSymbolOfSourceFile(fixture.path)
    if (!moduleSymbol) {
      results.push({
        tool: 'semantic',
        fixture: fixture.name,
        durationMs: performance.now() - start,
        output: {},
        error: 'no module symbol',
      })
      continue
    }

    const exports = await checker.getExportsOfModule(moduleSymbol)
    let foundAny = false

    for (const exp of exports) {
      const type = await checker.getTypeOfSymbol(exp)
      const callSignatures = await checker.getSignaturesOfType(type, SignatureKind.Call)
      let match = await findComponentSignature(callSignatures)
      let propsType: any

      if (match) {
        const location = await match.param.valueDeclaration.resolve()
        propsType = await checker.getTypeOfSymbolAtLocation(match.param, location)
      } else {
        // Class component: props come off the instance type's `props` member (doc step 2).
        const constructSignatures = await checker.getSignaturesOfType(type, SignatureKind.Construct)
        for (const sig of constructSignatures) {
          const params = await sig.getParameters()
          if (params.length > 1) continue
          const instanceType = await sig.getReturnType()
          const propsSymbol = await checker.getPropertyOfType(instanceType, 'props')
          if (!propsSymbol) continue
          match = { param: propsSymbol }
          propsType = await checker.getTypeOfSymbol(propsSymbol)
          break
        }
      }

      if (!match || !propsType) continue // not a component

      foundAny = true
      const location = match.param.valueDeclaration ? await match.param.valueDeclaration.resolve() : undefined
      const propsByName = await collectProps(propsType)
      const props = Object.fromEntries(
        await Promise.all(
          [...propsByName.values()].map(async (p) => [p.name, await normalizeProp(p, location)] as const),
        ),
      )

      results.push({
        tool: 'semantic',
        fixture: `${fixture.name}/${exp.name}`,
        durationMs: performance.now() - start,
        output: {
          [exp.name]: {
            displayName: exp.name,
            description: await exp.getDocumentationComment(checker),
            props,
          },
        },
      })
    }

    if (!foundAny) {
      results.push({
        tool: 'semantic',
        fixture: fixture.name,
        durationMs: performance.now() - start,
        output: {},
        error: 'no components found',
      })
    }
  } catch (error: any) {
    results.push({
      tool: 'semantic',
      fixture: fixture.name,
      durationMs: performance.now() - start,
      output: {},
      error: error.message,
    })
  }
}

await program.dispose()
await api.close()

console.log(JSON.stringify(results, null, 2))

