import { readFileSync, existsSync } from 'node:fs'
import type { ToolResult } from './types.ts'

// Checks that the tsc-api algorithm in run-semantic.ts reproduces real RDT's output —
// the "Evidence" section of docs/type-checker-integration.md. This is a parity check
// between two implementations of the same algorithm, not a quality comparison (that's
// compare.ts/analyze.ts, which weigh oxc-react-docgen's structural resolver against RDT).

function loadBaseline(name: string): Map<string, ToolResult> {
  const p = `./baselines/${name}.json`
  if (!existsSync(p)) {
    console.error(`Missing ./baselines/${name}.json — run \`pnpm baseline\` first.`)
    process.exit(1)
  }
  const results: ToolResult[] = JSON.parse(readFileSync(p, 'utf8'))
  return new Map(results.map((r) => [r.fixture, r]))
}

// RDT runs `.replace(' | undefined', '')` twice on every type string (see docs/
// type-checker-integration.md, "Evidence") — that's lossy (`=> string | undefined`
// becomes `=> string`), so replicate the quirk here rather than "fixing" RDT's output,
// or every optional prop's type would show up as a spurious mismatch.
function rdtTypeString(s: string): string {
  return s.replace(' | undefined', '').replace(' | undefined', '')
}

// tsc prints union members in internal type-id order, which differs from TS 5.9's
// (RDT's) order, so members are compared as a set rather than a verbatim string.
function typesMatch(oursType: string, rdtRawType: string): boolean {
  const rdtType = rdtTypeString(rdtRawType)
  if (oursType === rdtType) return true
  const a = oursType.split('|').map((m) => m.trim())
  const b = rdtType.split('|').map((m) => m.trim())
  return a.length > 1 && a.length === b.length && new Set(a).size === new Set([...a, ...b]).size
}

const rdt = loadBaseline('react-docgen-typescript')
const semantic = loadBaseline('semantic')

let componentsCompared = 0
let propsUnion = 0
let missing = 0
let extra = 0
let requiredMatched = 0
let requiredTotal = 0
let typeMatched = 0
let typeTotal = 0
let descriptionMatched = 0
let descriptionTotal = 0
const mismatches: string[] = []

for (const [key, rdtResult] of rdt) {
  const semanticResult = semantic.get(key)
  if (!semanticResult || rdtResult.error || semanticResult.error) continue

  const [rdtComp] = Object.values(rdtResult.output)
  const [semanticComp] = Object.values(semanticResult.output)
  if (!rdtComp || !semanticComp) continue

  componentsCompared++
  descriptionTotal++
  if (rdtComp.description.trim() === semanticComp.description.trim()) descriptionMatched++
  else mismatches.push(`${key}: description differs`)

  const allPropNames = new Set([...Object.keys(rdtComp.props), ...Object.keys(semanticComp.props)])
  for (const propName of allPropNames) {
    const rp = rdtComp.props[propName]
    const sp = semanticComp.props[propName]
    propsUnion++

    if (!sp) {
      missing++
      mismatches.push(`${key}.${propName}: missing (rdt has it, semantic doesn't)`)
      continue
    }
    if (!rp) {
      extra++
      mismatches.push(`${key}.${propName}: extra (semantic has it, rdt doesn't)`)
      continue
    }

    requiredTotal++
    if (rp.required === sp.required) requiredMatched++
    else mismatches.push(`${key}.${propName}: required rdt=${rp.required} semantic=${sp.required}`)

    typeTotal++
    if (typesMatch(sp.type, rp.type)) typeMatched++
    else mismatches.push(`${key}.${propName}: type rdt="${rp.type}" semantic="${sp.type}"`)
  }
}

console.log(`Components compared: ${componentsCompared}`)
console.log(`Props in union: ${propsUnion}`)
console.log(`  missing (in rdt, not semantic): ${missing}`)
console.log(`  extra (in semantic, not rdt):   ${extra}`)
console.log(`  required: ${requiredMatched}/${requiredTotal}`)
console.log(`  type strings: ${typeMatched}/${typeTotal}`)
console.log(`  descriptions: ${descriptionMatched}/${descriptionTotal}`)

if (mismatches.length > 0) {
  console.log(`\n${mismatches.length} mismatches:`)
  for (const m of mismatches.slice(0, 50)) console.log(`  ${m}`)
  if (mismatches.length > 50) console.log(`  ... and ${mismatches.length - 50} more`)
}

